demo.css:
ul { font: 14px var(--demo-mono); list-style: none; padding: 0; }
li { padding: 4px 8px; opacity: .35; }
li::before { content: "○ "; }
@media (display-state: normal) { .n { opacity: 1; color: var(--demo-accent); } .n::before { content: "● "; } }
@media (display-state: maximized) { .mx { opacity: 1; color: var(--demo-accent); } .mx::before { content: "● "; } }
@media (display-state: fullscreen) { .fs { opacity: 1; color: var(--demo-accent); } .fs::before { content: "● "; } }
@media (resizable: true) { .rt { opacity: 1; color: var(--demo-accent); } .rt::before { content: "● "; } }
@media (resizable: false) { .rf { opacity: 1; color: var(--demo-accent); } .rf::before { content: "● "; } }
